window.scraperData = {
  /**
   * Checks if the content to be scraped is ready and scrolls the page slowly to the end
   * to ensure all dynamic content is loaded.
   * @returns {Promise<void>} A promise that resolves when the scrolling is complete.
   */
  onloadComplete: async function() {
    const scrollStep = 500; // Pixels to scroll at a time
    const scrollDelay = 300; // Milliseconds delay between scrolls
    const maxScrollAttempts = 20; // Max attempts to scroll down, prevents infinite loops
    let currentScrollAttempt = 0;

    console.log("onloadComplete: Starting initial content check and scroll.");

    // Wait for a reliable indicator that content is present, e.g., the video grid container
    const contentReadySelector = 'div.relative.flex.flex-wrap.justify-center.gap-6';
    let contentContainer = document.querySelector(contentReadySelector);

    if (!contentContainer) {
      console.warn(`onloadComplete: Main content container "${contentReadySelector}" not found. Waiting for it to appear.`);
      // Implement a basic retry loop if the container isn't immediately available
      let attempts = 0;
      const maxAttempts = 10;
      while (!contentContainer && attempts < maxAttempts) {
        await new Promise(resolve => setTimeout(resolve, 1000)); // Wait 1 second
        contentContainer = document.querySelector(contentReadySelector);
        attempts++;
      }
      if (!contentContainer) {
        console.error("onloadComplete: Main content container still not found after multiple retries. Aborting scroll.");
        return;
      }
    }
    console.log("onloadComplete: Content container found. Initiating slow scroll.");

    return new Promise(resolve => {
      const scrollInterval = setInterval(() => {
        const currentScrollHeight = document.documentElement.scrollTop + window.innerHeight;
        const totalScrollHeight = document.documentElement.scrollHeight;

        // If we reached the end of the page or max scroll attempts, stop
        if (currentScrollHeight >= totalScrollHeight || currentScrollAttempt >= maxScrollAttempts) {
          clearInterval(scrollInterval);
          console.log("onloadComplete: Scrolling finished or maximum scroll attempts reached.");
          resolve();
        } else {
          // Scroll down by a step
          window.scrollBy(0, scrollStep);
          currentScrollAttempt++;
          console.log(`onloadComplete: Scrolled to ${window.scrollY}px. Attempt ${currentScrollAttempt}/${maxScrollAttempts}`);
        }
      }, scrollDelay);
    });
  },

  /**
   * Clicks the "Next Page" button if it exists and is not disabled.
   * @returns {boolean} True if the button was clicked, false otherwise (e.g., no more pages).
   */
  nextPage: function() {
    console.log("nextPage: Attempting to click the next page button.");
    // Select the next page button using its data attributes
    const nextPageButton = document.querySelector('a[data-cy="pagination-next"][data-testid="pagination-next"]');

    // Check if the button exists and is not visually or functionally disabled
    if (nextPageButton && !nextPageButton.hasAttribute('aria-disabled')) {
      nextPageButton.click();
      console.log("nextPage: Next page button clicked successfully.");
      return true;
    } else {
      console.log("nextPage: Next page button not found or is disabled.");
      return false;
    }
  },

  /**
   * Fetches all video links and their descriptions from the currently displayed page.
   * Formats the result as a JSON array with 'video_link' and 'desp' keys.
   * @returns {Array<Object>} An array of objects, each containing video_link and desp.
   */
  fetchContent: function() {
    console.log("fetchContent: Starting content extraction for videos.");
    const videosData = [];
    // Select all article elements that represent video thumbnails
    const videoArticles = document.querySelectorAll('article[data-cy="resource-thumbnail"]');

    if (!videoArticles || videoArticles.length === 0) {
      console.warn("fetchContent: No video articles found on the page.");
      return videosData; // Return an empty array if no articles are found
    }

    videoArticles.forEach(article => {
      let videoLink = null;
      let description = null;

      // Find the anchor element within the article to get the description (aria-label)
      const anchorElement = article.querySelector('a');
      if (anchorElement) {
        description = anchorElement.ariaLabel || null; // Use ariaLabel for description
      } else {
        console.warn("fetchContent: Anchor element not found for a video article, skipping description.");
      }

      // Find the video element within the article
      const videoElement = article.querySelector('video');
      if (videoElement) {
        // Find the source element within the video element to get the downloadable link
        const sourceElement = videoElement.querySelector('source');
        if (sourceElement && sourceElement.dataset.src) {
          videoLink = sourceElement.dataset.src; // Use data-src for the video link
        } else {
          console.warn("fetchContent: Source element or its 'data-src' attribute not found for a video, skipping link.");
        }
      } else {
        console.warn("fetchContent: Video element not found for a video article, skipping link.");
      }

      // Only add to the results array if both video_link and description are available
      if (videoLink && description) {
        videosData.push({
          video_link: videoLink,
          desp: description
        });
      } else {
        console.warn("fetchContent: Skipping a video entry due to missing video_link or description.");
      }
    });

    console.log(`fetchContent: Successfully extracted ${videosData.length} video entries.`);
    return videosData;
  }
};
